function middleware(request: Request): Context {
	const correlationId = crypto.randomUUID();
	logger.info({ correlation_id: correlationId, msg: "request received" });
	return { correlationId };
}

function callNext(context: Context, url: string): Promise<Response> {
	return fetch(url, { headers: { "X-Correlation-Id": context.correlationId } });
}

